#!/usr/bin/env python3\n\"\"\"\nGoogle Reviews Chatbot - Installation and Setup Script\nComplete installation and configuration assistant\n\"\"\"\n\nimport os\nimport sys\nimport subprocess\nimport json\nfrom pathlib import Path\n\ndef print_header():\n    print(\"\"\"\n🤖 Google Reviews Chatbot - Installation & Setup\n==============================================\n\nThis script will help you install and configure the Google Reviews Chatbot.\n\"\"\")\n\ndef check_python_version():\n    \"\"\"Check Python version compatibility\"\"\"\n    print(\"🐍 Checking Python version...\")\n    version = sys.version_info\n    \n    if version.major < 3 or (version.major == 3 and version.minor < 8):\n        print(f\"❌ Python {version.major}.{version.minor} detected\")\n        print(\"   This application requires Python 3.8 or higher\")\n        print(\"   Please upgrade Python and try again\")\n        return False\n    else:\n        print(f\"✅ Python {version.major}.{version.minor}.{version.micro} - Compatible\")\n        return True\n\ndef check_dependencies():\n    \"\"\"Check and install dependencies\"\"\"\n    print(\"\\n📦 Checking dependencies...\")\n    \n    required_packages = [\n        'flask',\n        'flask-cors', \n        'google-auth',\n        'google-api-python-client',\n        'openai',\n        'celery',\n        'redis',\n        'python-dotenv',\n        'requests'\n    ]\n    \n    missing_packages = []\n    available_packages = []\n    \n    for package in required_packages:\n        try:\n            __import__(package.replace('-', '_'))\n            available_packages.append(package)\n            print(f\"  ✅ {package}\")\n        except ImportError:\n            missing_packages.append(package)\n            print(f\"  ❌ {package}\")\n    \n    if missing_packages:\n        print(f\"\\n⚠️  Missing {len(missing_packages)} packages: {', '.join(missing_packages)}\")\n        \n        install_choice = input(\"\\nWould you like to install missing packages? (y/n): \").lower()\n        if install_choice in ['y', 'yes']:\n            return install_packages(missing_packages)\n        else:\n            print(\"📝 To install manually, run:\")\n            print(f\"   pip install {' '.join(missing_packages)}\")\n            return False\n    else:\n        print(f\"\\n✅ All {len(available_packages)} required packages are installed!\")\n        return True\n\ndef install_packages(packages):\n    \"\"\"Install missing packages\"\"\"\n    print(f\"\\n📥 Installing {len(packages)} packages...\")\n    \n    try:\n        cmd = [sys.executable, '-m', 'pip', 'install'] + packages\n        result = subprocess.run(cmd, capture_output=True, text=True)\n        \n        if result.returncode == 0:\n            print(\"✅ All packages installed successfully!\")\n            return True\n        else:\n            print(f\"❌ Installation failed: {result.stderr}\")\n            return False\n            \n    except Exception as e:\n        print(f\"❌ Error during installation: {e}\")\n        return False\n\ndef setup_environment():\n    \"\"\"Setup environment variables\"\"\"\n    print(\"\\n🔧 Environment Configuration\")\n    \n    env_file = Path('.env')\n    \n    if env_file.exists():\n        print(\"✅ .env file already exists\")\n        update_choice = input(\"Would you like to update configuration? (y/n): \").lower()\n        if update_choice not in ['y', 'yes']:\n            return True\n    \n    print(\"\\nConfiguring API keys and settings...\")\n    print(\"(Press Enter to skip any field)\\n\")\n    \n    # Google My Business API\n    print(\"🔗 Google My Business API Configuration:\")\n    print(\"   Get credentials at: https://console.cloud.google.com/\")\n    google_api_key = input(\"   Google API Key: \").strip()\n    google_client_id = input(\"   Google Client ID: \").strip()\n    google_client_secret = input(\"   Google Client Secret: \").strip()\n    \n    # OpenAI API\n    print(\"\\n🧠 OpenAI API Configuration:\")\n    print(\"   Get API key at: https://platform.openai.com/api-keys\")\n    openai_api_key = input(\"   OpenAI API Key: \").strip()\n    \n    # Redis configuration\n    print(\"\\n🔴 Redis Configuration:\")\n    redis_url = input(\"   Redis URL [redis://localhost:6379/0]: \").strip() or \"redis://localhost:6379/0\"\n    \n    # Flask configuration\n    print(\"\\n🌐 Flask Server Configuration:\")\n    host = input(\"   Host [0.0.0.0]: \").strip() or \"0.0.0.0\"\n    port = input(\"   Port [3000]: \").strip() or \"3000\"\n    debug = input(\"   Debug mode [True]: \").strip() or \"True\"\n    \n    # Create .env content\n    env_content = f\"\"\"# Google My Business API Configuration\nGOOGLE_API_KEY={google_api_key}\nGOOGLE_CLIENT_ID={google_client_id}\nGOOGLE_CLIENT_SECRET={google_client_secret}\n\n# OpenAI API Configuration\nOPENAI_API_KEY={openai_api_key}\n\n# Redis Configuration (for Celery)\nREDIS_URL={redis_url}\n\n# Flask Application Configuration\nDEBUG={debug}\nPORT={port}\nHOST={host}\n\n# Celery Configuration\nCELERY_ALWAYS_EAGER=False\n\"\"\"\n    \n    try:\n        with open('.env', 'w') as f:\n            f.write(env_content)\n        print(\"\\n✅ Environment configuration saved to .env\")\n        return True\n    except Exception as e:\n        print(f\"\\n❌ Error saving configuration: {e}\")\n        return False\n\ndef test_configuration():\n    \"\"\"Test the configuration\"\"\"\n    print(\"\\n🧪 Testing configuration...\")\n    \n    try:\n        # Test basic imports\n        from dotenv import load_dotenv\n        load_dotenv()\n        \n        # Test Google APIs\n        try:\n            from google.oauth2 import service_account\n            google_available = True\n        except ImportError:\n            google_available = False\n        \n        # Test OpenAI\n        try:\n            import openai\n            openai_available = True\n        except ImportError:\n            openai_available = False\n        \n        # Test Celery\n        try:\n            from celery import Celery\n            celery_available = True\n        except ImportError:\n            celery_available = False\n        \n        # Test Flask\n        try:\n            from flask import Flask\n            flask_available = True\n        except ImportError:\n            flask_available = False\n        \n        print(f\"  Google APIs: {'✅' if google_available else '❌'}\")\n        print(f\"  OpenAI: {'✅' if openai_available else '❌'}\")\n        print(f\"  Celery: {'✅' if celery_available else '❌'}\")\n        print(f\"  Flask: {'✅' if flask_available else '❌'}\")\n        \n        # Check environment variables\n        google_configured = all([\n            os.getenv('GOOGLE_API_KEY'),\n            os.getenv('GOOGLE_CLIENT_ID'),\n            os.getenv('GOOGLE_CLIENT_SECRET')\n        ])\n        \n        openai_configured = bool(os.getenv('OPENAI_API_KEY'))\n        \n        print(f\"  Google configured: {'✅' if google_configured else '❌'}\")\n        print(f\"  OpenAI configured: {'✅' if openai_configured else '❌'}\")\n        \n        if all([google_available, openai_available, celery_available, flask_available]):\n            if google_configured and openai_configured:\n                print(\"\\n🎉 Full functionality available!\")\n                return 'full'\n            else:\n                print(\"\\n⚠️  Dependencies installed but API keys missing\")\n                return 'partial'\n        else:\n            print(\"\\n⚠️  Some dependencies missing - limited functionality\")\n            return 'limited'\n            \n    except Exception as e:\n        print(f\"\\n❌ Error testing configuration: {e}\")\n        return 'error'\n\ndef show_usage_instructions(config_status):\n    \"\"\"Show how to use the application\"\"\"\n    print(\"\\n📋 Usage Instructions\")\n    print(\"====================\\n\")\n    \n    if config_status == 'full':\n        print(\"🎉 Your installation is complete! Here's how to use it:\\n\")\n        \n        print(\"1. Start the main application:\")\n        print(\"   python3 google_reviews_chatbot.py\")\n        print(\"   OR\")\n        print(\"   python3 app.py\")\n        \n        print(\"\\n2. Start Celery worker (in separate terminal):\")\n        print(\"   python3 start_celery.py worker\")\n        \n        print(\"\\n3. Start Celery beat scheduler (in separate terminal):\")\n        print(\"   python3 start_celery.py beat\")\n        \n        print(\"\\n4. Or start everything with:\")\n        print(\"   python3 start_celery.py all\")\n        \n    elif config_status in ['partial', 'limited']:\n        print(\"⚠️  Limited functionality mode:\\n\")\n        \n        print(\"1. Start the application:\")\n        print(\"   python3 google_reviews_chatbot.py\")\n        \n        print(\"\\n2. The app will run with mock data and simulated responses\")\n        \n        if config_status == 'partial':\n            print(\"\\n3. Add missing API keys to .env file for full functionality\")\n    \n    print(\"\\n🌐 Access the application at: http://localhost:3000\")\n    \n    print(\"\\n📚 Additional Information:\")\n    print(\"   • Web interface: Full dashboard with testing tools\")\n    print(\"   • API endpoints: RESTful API for integration\")\n    print(\"   • Real-time processing: Automatic review fetching\")\n    print(\"   • Documentation: Check README.md for more details\")\n    \n    print(\"\\n🔧 Configuration files:\")\n    print(\"   • .env - Environment variables\")\n    print(\"   • requirements.txt - Python dependencies\")\n    print(\"   • celery_config.py - Task scheduling configuration\")\n\ndef main():\n    print_header()\n    \n    # Check Python version\n    if not check_python_version():\n        return\n    \n    # Check and install dependencies\n    deps_ok = check_dependencies()\n    \n    # Setup environment\n    env_ok = setup_environment()\n    \n    # Test configuration\n    config_status = test_configuration()\n    \n    # Show usage instructions\n    show_usage_instructions(config_status)\n    \n    print(\"\\n✨ Setup complete! Enjoy using Google Reviews Chatbot!\")\n\nif __name__ == '__main__':\n    main()\n
